create table public.discounts (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, code text not null, kind text not null check(kind in ('percent','fixed')), amount integer not null check(amount > 0), currency char(3), starts_at timestamptz, ends_at timestamptz, usage_limit integer check(usage_limit is null or usage_limit > 0), usage_count integer not null default 0 check(usage_count >= 0), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(store_id,code), check(ends_at is null or starts_at is null or ends_at > starts_at));
